from collections import Counter

def transform_v2(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    sections=[]
    r=0
    while r<h:
        if all(v==bg for v in grid[r]):
            r+=1; continue
        start=r
        while r<h and any(v!=bg for v in grid[r]):
            r+=1
        sections.append((start,r))
    if len(sections)!=2 or sections[0][1]-sections[0][0] != sections[1][1]-sections[1][0]:
        return [row[:] for row in grid]
    (a0,a1),(b0,b1)=sections
    band=a1-a0
    candidates=[]
    for orient,(s0,t0) in enumerate(((a0,b0),(b0,a0))):
        for k in range(1,(w-1)//3+1):
            marks=[]; valid_rows=[]
            for off in range(band):
                source=grid[s0+off]; target=grid[t0+off]
                pred=source[:2*k]+source[:k]+source[2*k:w-k]
                last=max((c for c,v in enumerate(target) if v!=bg),default=-1)
                if pred[:last+1] != target[:last+1]:
                    continue
                valid_rows.append(off)
                for c in range(last+1,w):
                    if pred[c]!=bg:
                        marks.append((t0+off,c))
            if marks:
                candidates.append((len(marks),-len(valid_rows),k,orient,marks))
    if not candidates:
        return [row[:] for row in grid]
    _,_,_,_,marks=min(candidates)
    output=[row[:] for row in grid]
    for r,c in marks:
        output[r][c]=1
    return output

